package com.taller.gestion.config;
import com.taller.gestion.repository.UserRepository; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableWebSecurity public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){ return new BCryptPasswordEncoder(); } @Bean UserDetailsService users(UserRepository users){return email->{var u=users.findByEmail(email).orElseThrow(()->new UsernameNotFoundException(email));String[] roles=u.getRoles().stream().map(r->"ROLE_"+r.name()).toArray(String[]::new);return org.springframework.security.core.userdetails.User.withUsername(u.getEmail()).password(u.getPasswordHash()).authorities(roles).build();};} @Bean SecurityFilterChain filterChain(HttpSecurity http) throws Exception { return http.csrf(csrf->csrf.disable()).cors(cors->{}).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/actuator/health").permitAll().requestMatchers("/api/admin/**").hasRole("ADMINISTRADOR").requestMatchers("/api/orders/**","/api/parts/**").hasAnyRole("ADMINISTRADOR","SECRETARIA","MECANICO").anyRequest().authenticated()).httpBasic(b->{}).build(); } }
